private void makeGrid(char[][] map, int width, int height, nl.tudelft.jpacman.board.Square[][] grid, java.util.List<nl.tudelft.jpacman.npc.Ghost> ghosts, java.util.List<nl.tudelft.jpacman.board.Square> startPositions) {
    for (int x = 0; x < width; x++) {
        for (int y = 0; y < height; y++) {
            char c = map[x][y];
            this.addSquare(grid, ghosts, startPositions, x, y, c);
        }
    }
}

protected final boolean invariant(nl.tudelft.jpacman.board.Square this) {
    for (nl.tudelft.jpacman.board.Unit occupant : this.occupants) {
        if (occupant.hasSquare() && (occupant.getSquare() != this)) {
            return false;
        }
    }
    return true;
}

