public nl.tudelft.jpacman.level.Level parseMap(java.io.InputStream source) throws java.io.IOException {
    try (java.io.BufferedReader reader = new java.io.BufferedReader(new java.io.InputStreamReader(source, "UTF-8"))) {
        java.util.List<java.lang.String> lines = new java.util.ArrayList<java.lang.String>();
        while (reader.ready()) {
            lines.add(reader.readLine());
        } 
        return this.parseMap(lines);
    }
}

