public void start() {
    synchronized(this.progressLock) {
        if (this.isInProgress()) {
            return;
        }
        if (this.getLevel().isAnyPlayerAlive() && (this.getLevel().remainingPellets() > 0)) {
            this.inProgress = true;
            this.getLevel().addObserver(this);
            this.getLevel().start();
        }
    }
}

