protected nl.tudelft.jpacman.board.Direction randomMove() {
    nl.tudelft.jpacman.board.Square square = this.getSquare();
    java.util.List<nl.tudelft.jpacman.board.Direction> directions = new java.util.ArrayList<nl.tudelft.jpacman.board.Direction>();
    for (nl.tudelft.jpacman.board.Direction direction : nl.tudelft.jpacman.board.Direction.values()) {
        if (square.getSquareAt(direction).isAccessibleTo(this)) {
            directions.add(direction);
        }
    }
    if (directions.isEmpty()) {
        return null;
    }
    int i = new java.util.Random().nextInt(directions.size());
    return directions.get(i);
}

