public void stop() {
    synchronized(this.startStopLock) {
        if (!this.isInProgress()) {
            return;
        }
        this.stopNPCs();
        this.inProgress = false;
    }
}

public void respawn() {
    int i = 0;
    java.util.Iterator<nl.tudelft.jpacman.npc.Ghost> ghostIterator = this.npcs.keySet().iterator();
    for (nl.tudelft.jpacman.board.Square square : this.startSquares) {
        if (square.getSpawnType().equals(nl.tudelft.jpacman.level.Player.class)) {
            this.players.get(i).occupy(square);
            i += 1;
        } else if (square.getSpawnType().equals(nl.tudelft.jpacman.npc.Ghost.class)) {
            ghostIterator.next().occupy(square);
        }
    }
}

