public java.util.Optional<nl.tudelft.jpacman.board.Direction> nextAiMove() {
    assert this.hasSquare();
    nl.tudelft.jpacman.board.Unit blinky = nl.tudelft.jpacman.npc.ghost.Navigation.findNearest(nl.tudelft.jpacman.npc.ghost.Blinky.class, this.getSquare());
    nl.tudelft.jpacman.board.Unit player = nl.tudelft.jpacman.npc.ghost.Navigation.findNearest(nl.tudelft.jpacman.level.Player.class, this.getSquare());
    if ((blinky == null) || (player == null)) {
        return java.util.Optional.empty();
    }
    assert player.hasSquare();
    nl.tudelft.jpacman.board.Square playerDestination = player.squaresAheadOf(nl.tudelft.jpacman.npc.ghost.Inky.SQUARES_AHEAD);
    java.util.List<nl.tudelft.jpacman.board.Direction> firstHalf = nl.tudelft.jpacman.npc.ghost.Navigation.shortestPath(blinky.getSquare(), playerDestination, null);
    if (firstHalf == null) {
        return java.util.Optional.empty();
    }
    nl.tudelft.jpacman.board.Square destination = this.followPath(firstHalf, playerDestination);
    java.util.List<nl.tudelft.jpacman.board.Direction> path = nl.tudelft.jpacman.npc.ghost.Navigation.shortestPath(this.getSquare(), destination, this);
    if ((path != null) && (!path.isEmpty())) {
        return java.util.Optional.ofNullable(path.get(0));
    }
    return java.util.Optional.empty();
}

