public static <T extends nl.tudelft.jpacman.board.Unit> T findUnitInBoard(java.lang.Class<T> clazz, nl.tudelft.jpacman.board.Board board) {
    for (int y = 0; y < board.getHeight(); y++) {
        for (int x = 0; x < board.getWidth(); x++) {
            final T ghost = nl.tudelft.jpacman.npc.ghost.Navigation.findUnit(clazz, board.squareAt(x, y));
            if (ghost != null) {
                return ghost;
            }
        }
    }
    return null;
}

