@java.lang.Override
public java.util.Optional<nl.tudelft.jpacman.board.Direction> nextAiMove() {
    assert this.hasSquare();
    nl.tudelft.jpacman.board.Unit nearest = nl.tudelft.jpacman.npc.ghost.Navigation.findNearest(nl.tudelft.jpacman.level.Player.class, this.getSquare());
    if (nearest == null) {
        return java.util.Optional.empty();
    }
    assert nearest.hasSquare();
    nl.tudelft.jpacman.board.Square target = nearest.getSquare();
    java.util.List<nl.tudelft.jpacman.board.Direction> path = nl.tudelft.jpacman.npc.ghost.Navigation.shortestPath(this.getSquare(), target, this);
    if ((path != null) && (!path.isEmpty())) {
        nl.tudelft.jpacman.board.Direction direction = path.get(0);
        if (path.size() <= nl.tudelft.jpacman.npc.ghost.Clyde.SHYNESS) {
            return java.util.Optional.of(direction.opposite());
        }
        return java.util.Optional.of(direction);
    }
    return java.util.Optional.empty();
}

private nl.tudelft.jpacman.level.Player getSinglePlayer(final nl.tudelft.jpacman.game.Game game) {
    java.util.List<nl.tudelft.jpacman.level.Player> players = game.getPlayers();
    if (players.isEmpty()) {
        throw new java.lang.IllegalArgumentException("Game has 0 players.");
    }
    return players.get(0);
}

